// ============================================================
// VALIDATION DU RAPPEL DE LOT — vocalisation
// ============================================================
// Appelé par `Claude - Batch Poller` (`POST Callback`) quand le lot Anthropic est
// terminé. Le poller retire `api_key` et `callback_url` avant d'envoyer.
const input = $input.first().json;
const body = input.body || input;

// ⚠️ `metadata` peut arriver en CHAÎNE JSON. C'est le cas défensif déjà rencontré
// sur le callback de traduction : le lot a traversé Redis, et selon le chemin la
// metadata en ressort sérialisée. Sans ce parse, `carte_items` est undefined et
// TOUS les résultats deviennent non rattachables — un lot entier payé puis jeté.
let md = body.metadata;
if (typeof md === 'string') {
  try { md = JSON.parse(md); } catch (e) { md = {}; }
}
md = md || {};

const resultats = Array.isArray(body.results) ? body.results : [];
const errors = [];
if (resultats.length === 0) {
  errors.push('Aucun resultat dans le rappel du lot');
}
// Sans la carte, un résultat n'est rattachable à rien : le texte est payé, produit,
// et impossible à écrire. On refuse bruyamment plutôt que d'écrire au hasard.
if (!md.carte_items || typeof md.carte_items !== 'object') {
  errors.push('metadata.carte_items absente — resultats non rattachables');
}

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    data: {
      job_id: md.job_id || body.job_id || null,
      project_id: md.project_id || null,
      batch_id: body.batch_id || null,
      correlation_id: body.correlation_id || md.correlation_id || null,
      client_metadata: md.client_metadata || null,
      // ⚠️ Aucune valeur de repli inventée : `anthropic` est ici une CERTITUDE, pas
      // un défaut — le dispatcher refuse tout modèle non Claude, et les Message
      // Batches n'existent que chez Anthropic. Le modèle, lui, vient du lot.
      provider: md.provider || 'anthropic',
      model: md.model || null,
      traite: md.traite || null,
      page: md.page || null,
      carte_items: md.carte_items || {},
      results: resultats
    }
  }
}];

// ============================================================
// ÉCLATER LES RÉSULTATS — un item n8n par vocalisation
// ============================================================
const data = $input.first().json.data;
const carte = data.carte_items || {};
const resultats = data.results || [];

// ⚠️ LE PIÈGE MULTI-FOURNISSEURS, repris de `Recoller Vocalisation`. Chaque
// fournisseur nomme différemment une génération terminée, et le lot passe par
// Anthropic : `end_turn` / `stop_sequence` sont NORMAUX, `max_tokens` est une
// troncature. Tester `!== 'stop'` (la forme d'OpenAI) déclarerait tronquée
// CHAQUE réponse du lot, et la vocalisation échouerait systématiquement.
const FINS_NORMALES = ['end_turn', 'stop_sequence', 'stop'];

// ⚠️ UN `stop_reason` ABSENT N'EST PAS UNE TRONCATURE. Le poller ne remonte ce
// champ que depuis azy.daily#706 : si `Claude - Batch Poller` n'est pas encore
// réimporté, il vaut `undefined` sur tous les items. Refuser dans ce cas
// jetterait un lot entier déjà payé à cause d'un ordre de réimport. On ne refuse
// donc QUE sur une valeur PRÉSENTE et anormale.
const finAcceptable = (r) => r === undefined || r === null || r === ''
  || FINS_NORMALES.indexOf(String(r).toLowerCase()) !== -1;

// ⚠️ `vocalized_by` est ÉCRIT EN BASE côté torah.api. On garde EXACTEMENT la forme
// `llm:<modele>` du chemin synchrone, pour qu'aucun consommateur n'ait à
// distinguer une ligne venue du lot d'une ligne venue du direct. La provenance
// reste lisible dans le nom du modèle (`llm:claude-…` contre `llm:gpt-4o`).
const signature = 'llm:' + (data.model || 'claude');

const items = resultats.map((r, rang) => {
  const ref = String(r && r.custom_id);
  const cible = carte[ref] || {};
  const texte = (r && typeof r.text === 'string') ? r.text.trim() : '';

  let souci = null;
  if (!r || r.ok !== true) {
    souci = { code: 'BATCH_ITEM_FAILED',
              message: String((r && r.error && (r.error.message || r.error.code)) || 'echec du lot') };
  } else if (!carte[ref]) {
    // Résultat sans cible : payé, produit, non rattachable. À remonter, jamais à écrire.
    souci = { code: 'CIBLE_INTROUVABLE',
              message: 'custom_id ' + ref + ' absent de carte_items' };
  } else if (!texte) {
    souci = { code: 'EMPTY_LLM_RESPONSE', message: 'le modele a rendu une reponse vide' };
  } else if (!finAcceptable(r.stop_reason)) {
    // Un texte tronqué enregistré comme complet, ce sont des nekudot manquantes en
    // fin de texte, sans aucune erreur. Même doctrine que le chemin synchrone.
    souci = { code: 'GENERATION_TRONQUEE',
              message: 'generation interrompue (stop_reason=' + String(r.stop_reason)
                     + ') texte tronque, non enregistre' };
  }

  return { json: {
    rang: rang,
    custom_id: ref,
    job_id: data.job_id,
    project_id: data.project_id,
    correlation_id: data.correlation_id,
    client_metadata: data.client_metadata,
    provider: data.provider,
    model: data.model,
    traite: data.traite,
    page: data.page,
    ok: !souci,
    error: souci,
    original: cible.original || null,
    vocalized_text: souci ? null : texte,
    // Forme EXACTE attendue par /api/vocalization/save, reprise de
    // `Extract GPT Response` du chemin synchrone : les trois identifiants sont
    // présents, à null quand ils ne s'appliquent pas.
    _saveData: souci ? null : {
      segment_id: cible.segment_id || null,
      source_text_id: cible.source_text_id || null,
      commentary_id: cible.commentary_id || null,
      vocalized_text: texte,
      vocalized_by: signature
    }
  }};
});

// ⚠️ SENTINELLE. Si RIEN n'est enregistrable, il ne faut pas pour autant que la
// chaîne s'arrête : le job doit être clos et l'appelant prévenu. Un nœud HTTP sans
// item d'entrée ne s'exécute pas, et la branche entière resterait muette — le job
// resterait « processing » pour toujours.
const aEnvoyer = items.filter((it) => it.json._saveData);
if (aEnvoyer.length === 0) {
  return [{ json: { aucun_envoi: true, job_id: data.job_id, project_id: data.project_id,
                    correlation_id: data.correlation_id, client_metadata: data.client_metadata,
                    traite: data.traite, page: data.page, total: items.length,
                    soucis: items.map((it) => it.json.error).filter(Boolean) } }];
}
return items;

// ============================================================
// GROUPER SAUVEGARDES — un appel pour N vocalisations, et non N appels
// ============================================================
// Jusqu'ici chaque vocalisation partait dans son propre POST /api/vocalization/save :
// sur une page de 71 commentaires, 71 allers-retours.
// /api/vocalization/save-batch (chatbot.api#369) prend N items et répond
// `per_item_results[]` COMPLET, dans l'ordre, avec un index d'entrée. Même contrat et
// même découpage que le lot de TRADUCTION (`Torah_Batch_Callback`).

const TAILLE_LOT = 500;

// ⚠️ PLAFOND DE TAILLE, EN PLUS du compte d'items. Mesuré sur trois exécutions de
// production (1323592, 1323682, 1323901 — 264 items réels) : un item pèse 1 117 o en
// médiane, 1 708 o en moyenne, et jusqu'à 8 673 o. Un lot de 500 fait donc ~0,9 Mo au
// cas courant, mais 4,3 Mo au pire — pour UN SEUL POST dont l'échec emporterait les 500.
//
// Le plafond est compté en CARACTÈRES, parce que c'est ce que `.length` rend. L'hébreu
// ponctué pèse 2 octets par caractère en UTF-8, donc 1 000 000 caractères valent ~2 Mo :
// le cas courant (≈300 000 caractères pour 500 items) passe en une seule tranche, et seuls
// les textes longs sont coupés plus tôt.
const CARACTERES_MAX = 1000000;

const tous = $input.all().map((i) => i.json);
const premier = tous[0] || {};

// `Éclater Résultats` émet DÉJÀ une sentinelle quand rien n'est enregistrable. On la
// relaie telle quelle plutôt que de la reconstruire : `Agréger` lit ainsi exactement la
// même forme qu'avant ce changement.
if (tous.length === 1 && premier.aucun_envoi === true) {
  return [{ json: premier }];
}

const aEcrire = tous.filter((it) => it._saveData);

// ⚠️ Un item en ÉCHEC (`_saveData: null`) ne part plus du tout. Avant ce changement il
// traversait `À Sauvegarder ?` — qui ne filtre que la sentinelle — et partait en POST avec
// le corps littéral `null`, que torah.api ne peut que refuser. L'appel était inutile, et
// son échec invisible, `continueRegularOutput` ne rendant aucun statusCode.
if (aEcrire.length === 0) {
  return [{ json: {
    aucun_envoi: true,
    job_id: premier.job_id || null,
    project_id: premier.project_id || null,
    correlation_id: premier.correlation_id || null,
    client_metadata: premier.client_metadata || null,
    traite: premier.traite || null,
    page: premier.page || null,
    total: tous.length,
    soucis: tous.map((it) => it.error).filter(Boolean)
  }}];
}

const lots = [];
let tranche = [];
let taille = 0;

const fermer = () => {
  if (tranche.length === 0) return;
  lots.push({ json: {
    aucun_envoi: false,
    lot_index: lots.length,
    // Recollage : /save-batch répond par INDEX D'ENTRÉE, pas par identifiant. Le `rang`
    // posé par `Éclater Résultats` est stable, donc le recollage est vérifiable en aval.
    rangs: tranche.map((it) => it.rang),
    items: tranche.map((it) => it._saveData)
  }});
  tranche = [];
  taille = 0;
};

aEcrire.forEach((it) => {
  const poids = JSON.stringify(it._saveData).length;
  if (tranche.length >= TAILLE_LOT || (tranche.length > 0 && taille + poids > CARACTERES_MAX)) {
    fermer();
  }
  tranche.push(it);
  taille += poids;
});
fermer();

return lots;

// ============================================================
// ÉCLATER SAUVEGARDES — recoller le sort de chaque vocalisation
// ============================================================
// /api/vocalization/save-batch répond 200 même quand des items échouent, et isole le
// détail dans `per_item_results[i]` avec l'index d'entrée. On remonte donc ce verdict sur
// chaque vocalisation, au lieu de conclure du seul code HTTP.
//
// La source de vérité reste `$('Éclater Résultats')` : il rend une ligne par résultat reçu
// d'Anthropic, Y COMPRIS celles jamais soumises à l'écriture (texte vide, tronqué, cible
// introuvable). L'agrégat en aval compte sur ce total.

const entrees = $input.all();

// Branche « rien à écrire » : la sentinelle traverse intacte, qu'elle vienne d'`Éclater
// Résultats` (aucun résultat exploitable) ou de `Grouper Sauvegardes` (tous en échec).
if (entrees.length === 1 && entrees[0].json && entrees[0].json.aucun_envoi === true) {
  return [{ json: entrees[0].json }];
}

const vocalisations = $('Éclater Résultats').all().map((i) => i.json);
const lots = $('Grouper Sauvegardes').all();

// ⚠️ Les rangs RÉELLEMENT soumis à l'écriture. Sans cette liste, un verdict manquant
// se confondait avec « jamais soumise » — deux causes opposées sous le même libellé :
// l'une désigne notre câblage, l'autre une réponse incomplète de torah.api. Un
// diagnostic qui accuse le mauvais maillon coûte plus cher que pas de diagnostic.
const soumis = {};

// Verdict par rang, alimenté par la réponse de chaque lot.
const verdicts = {};

// ⚠️ Appariement par POSITION, pas par contenu : la réponse HTTP ne rapporte rien du lot
// qui l'a produite. Le nœud HTTP émet un item de sortie par item d'entrée et dans le même
// ordre, donc `entrees[i]` correspond à `lots[i]`. C'est le seul endroit du workflow où
// l'ordre porte du sens.
for (let i = 0; i < entrees.length; i++) {
  const j = entrees[i].json;
  if (j.aucun_envoi) continue;

  // Avec onError=continueRegularOutput, un appel en échec n'émet PAS {statusCode, body} :
  // le statut réel est enfoui dans le message (« 500 - {…} »). Sans cette lecture, un lot
  // entièrement perdu passerait pour sauvegardé — c'est le défaut d'azy.daily#442.
  let code = j.statusCode;
  if (code === undefined) {
    const brut = String((j && j.error && j.error.message) || (j && j.message) || '');
    const m = brut.match(/(\d{3})\s*-\s*/);
    code = m ? parseInt(m[1], 10) : ((j && (j.error || j.code)) ? 502 : 200);
  }
  const corps = j.body || {};
  const rangs = ((lots[i] || {}).json || {}).rangs || [];
  rangs.forEach((r) => { soumis[r] = true; });

  // ⚠️ `per_item_results` absent est traité comme un ÉCHEC, jamais comme un succès muet.
  // Un 200 sans détail ne prouve aucune écriture.
  if (code >= 400 || !Array.isArray(corps.per_item_results)) {
    const motif = code >= 400
      ? ('save-batch HTTP ' + code)
      : 'save-batch, reponse sans per_item_results';
    rangs.forEach((r) => { verdicts[r] = { save_ok: false, save_error: motif }; });
    continue;
  }

  corps.per_item_results.forEach((res) => {
    const rang = rangs[res.index];
    // Un index hors carte ne doit rien écraser : l'absence vaut échec (voir plus bas).
    if (rang === undefined) return;
    verdicts[rang] = res.success
      ? { save_ok: true, save_error: null }
      : { save_ok: false,
          save_error: String((res.error && (res.error.detail || res.error.status_code))
                             || 'echec sauvegarde') };
  });
}

return vocalisations.map((v) => {
  const verdict = verdicts[v.rang];
  return { json: Object.assign({}, v, {
    // Une vocalisation en échec n'a JAMAIS été proposée à l'écriture : la compter comme un
    // échec de sauvegarde ferait perdre sa cause réelle (texte vide, tronqué, sans cible).
    save_ok: v.ok === true ? (verdict ? verdict.save_ok : false) : null,
    save_error: v.ok === true
      ? (verdict ? verdict.save_error
                 : (soumis[v.rang]
                    // Soumise, et torah.api n'en a rien dit. Son contrat annonce un
                    // per_item_results COMPLET et ordonné : un index absent est donc
                    // un écart au contrat, à remonter chez eux — pas chez nous.
                    ? 'soumise mais absente de per_item_results'
                    : 'jamais soumise a la sauvegarde'))
      : null
  })};
});

// ============================================================
// AGRÉGER — ce qui est réellement en base, et ce qui ne l'est pas
// ============================================================
// Entrée : la sortie d'`Éclater Sauvegardes`, soit une ligne par vocalisation portant son
// verdict d'écriture (`save_ok` / `save_error`), soit la sentinelle « rien à écrire ».
//
// ⚠️ Ce nœud ne lit PLUS les réponses HTTP par position. Avant le passage au lot, il
// appariait `reponses[i]` avec `prevus[i]` — un appel par item, donc un alignement qui
// tenait. Avec /save-batch il y a UNE réponse pour N items : l'alignement est fait en
// amont, par index d'entrée, et c'est `Éclater Sauvegardes` qui en porte la charge.

const entrees = $input.all().map((x) => x.json);
const sentinelle = entrees.length === 1 && entrees[0] && entrees[0].aucun_envoi === true;
const base = (sentinelle ? entrees[0] : entrees[0]) || {};

let enregistres = 0;
const echecs = [];

if (sentinelle) {
  (base.soucis || []).forEach((s) => echecs.push({ custom_id: null, error: s }));
} else {
  entrees.forEach((v) => {
    // 1 · jamais soumise : la cause d'origine est la seule intéressante.
    if (v.ok !== true) {
      echecs.push({ custom_id: v.custom_id, error: v.error });
      return;
    }
    // 2 · soumise et écrite.
    if (v.save_ok === true) {
      enregistres += 1;
      return;
    }
    // 3 · soumise et refusée. `save_ok` à false OU absent compte pour un échec : un
    //     verdict manquant veut dire que `per_item_results` était incomplet, et on ne
    //     déclare pas écrite une ligne dont personne n'a confirmé l'écriture.
    echecs.push({ custom_id: v.custom_id, error: {
      code: 'SAVE_FAILED',
      message: 'ecriture refusee par torah-api (' + String(v.save_error || 'cause inconnue') + ')'
    }});
  });
}

const total = sentinelle ? (base.total || 0) : entrees.length;
return [{ json: {
  success: enregistres > 0,
  job_id: base.job_id || null,
  project_id: base.project_id || null,
  correlation_id: base.correlation_id || null,
  client_metadata: base.client_metadata || null,
  traite: base.traite || null,
  page: base.page || null,
  resume: { total: total, enregistres: enregistres, echecs: echecs.length },
  echecs: echecs.slice(0, 20)
} }];

// ============================================================
// PRÉPARER L'ÉVÉNEMENT REDIS — fin de vocalisation
// ============================================================
// ⚠️ L'APPARIEMENT SE FAIT PAR `job_id` POUR LA VOCALISATION, pas par
// `correlation_id` (qui sert à l'export). Se tromper de clé publie un événement
// que personne ne sait rattacher.
//
// ⚠️ ET CET ÉVÉNEMENT N'A AUCUN CONSOMMATEUR À CE JOUR : le plugin est
// dispatch-only depuis #514/PR#275. Un XADD réussi prouve qu'on a PUBLIÉ, pas
// qu'on a été lu. L'appelant doit sonder /api/v2/jobs/{job_id} — c'est le seul
// canal qui fasse foi, et c'est pour ça que `Update Job` passe AVANT.
const r = $input.first().json;
const resume = r.resume || {};

// Pas de repli `|| ''` sur le job_id : il publierait du VIDE, qui ressemble à un
// événement valide et ne s'apparie à rien.
// ⚠️ DEUX ÉMETTEURS, UN SEUL DIALECTE. `Torah_Vocalization_Worker` publie le MÊME
// événement `vocalization_complete` sur le MÊME stream, mais nommait ses compteurs
// `ok_count` / `fail_count` là où celui-ci disait `enregistres` / `echecs`, et posait
// un `error_code` que celui-ci n'avait pas du tout.
//
// Un consommateur ne peut pas distinguer les deux à l'avance : il route sur `event`,
// qui est identique. Un écouteur écrit sur les noms du chemin synchrone — ce que le
// commentaire du worker recommande explicitement — lisait donc `undefined` sur TOUT
// événement de lot : zéro vocalisé affiché, ou une exception.
//
// Les quatre champs du synchrone sont AJOUTÉS, et aucun n'est retiré : `enregistres`
// et `echecs` restent, de sorte qu'aucun lecteur existant ne casse. Verrouillé par
// `scripts/test/test_evenement_vocalisation_dialecte.js`.
const total = Number(resume.total) || 0;
const echecs = Number(resume.echecs) || 0;
const enregistres = Number(resume.enregistres) || 0;

const champs = {
  event: 'vocalization_complete',
  job_id: String(r.job_id),
  mode: 'batch',
  success: String(!!r.success),
  total: String(total),
  // noms historiques de CE chemin — conservés
  enregistres: String(enregistres),
  echecs: String(echecs),
  // noms du chemin SYNCHRONE — ajoutés, mêmes valeurs
  ok_count: String(enregistres),
  fail_count: String(echecs),
  // ⚠️ Même convention que le synchrone : une CHAÎNE VIDE quand il n'y a rien à
  // signaler, et non une clé absente. Un flux Redis n'a pas de null, et une clé
  // absente se lit comme « personne n'a regardé » là où le vide dit « rien à dire ».
  error_code: (echecs === total && total > 0) ? 'ALL_FAILED' : '',
  error_message: echecs > 0 ? (echecs + ' item(s) en erreur') : '',
  traite: String(r.traite || ''),
  page: String(r.page || ''),
  completed_at: new Date().toISOString()
};
if (r.correlation_id) { champs.correlation_id = String(r.correlation_id); }

return [{ json: { stream: 'llm:results:stream', fields: champs, max_len: 10000 } }];

// Réponse au poller. Elle n'est lue par personne d'autre : le poller ne fait rien
// du corps, il journalise seulement le code. On la garde explicite pour les
// exécutions, qui sont la seule trace consultable après coup — et pour ~2,4 jours
// seulement, la rétention étant au COMPTE (~10 000) et non à la durée.
const r = $input.first().json;
return [{ json: {
  success: !!r.success,
  job_id: r.job_id || null,
  mode: 'batch',
  resume: r.resume || null,
  echecs: r.echecs || []
} }];

const v = $input.first().json;
return [{ json: {
  success: false,
  error: { code: 400, message: (v.errors || []).join(', '), status: 'BAD_REQUEST' }
} }];
